from math import comb

def f(nR, nB):
    """Calculates the total number of monochromatic triangles."""
    return comb(nR, 3) + comb(nB, 3)

def find_min_for_n(n):
    """Finds the minimum value of f(nR, nB) for a given n."""
    min_val = float('inf')
    # We only need to check partitions up to n//2 because f is symmetric
    for nR in range(n // 2 + 1):
        nB = n - nR
        min_val = min(min_val, f(nR, nB))
    return min_val

# Test n = 1 through 7
tests = list(range(1, 8))
results = {}
for n in tests:
    results[n] = find_min_for_n(n)

print(results)

import math

def combinations(n, k):
    if k < 0 or k > n:
        return 0
    return math.comb(n, k)

def min_mono_triangles(n):
    n_r = math.ceil(n / 2)
    n_b = math.floor(n / 2)

    # Minimum number of monochromatic triangles occurs when partitioning n into n_r and n_b
    mono_r = combinations(n_r, 3)
    mono_b = combinations(n_b, 3)
    return mono_r + mono_b

# Test small values of n
test_values = [3, 4, 5, 6, 7]
results = {n: min_mono_triangles(n) for n in test_values}

print(results)
